mapper.select:
SELECT s.id, s.name, s.price, s.status, s.description, s.image, s.category_id, s.update_time, s.create_time , category.name AS categoryName FROM setmeal s LEFT JOIN category ON s.category_id = category.id
AND s.name LIKE CONCAT('%', #{name}, '%')
AND s.category_id = #{categoryId}
AND s.status = #{status}
order by update_time DESC

SELECT setmeal_dish.id, setmeal_dish.setmeal_id, setmeal_dish.dish_id, setmeal_dish.name, setmeal_dish.price, setmeal_dish.copies
FROM setmeal_dish
WHERE setmeal_dish.setmeal_id = #{setmealId}

select * from setmeal

     and name like concat('%',#{name},'%') 
     and category_id = #{categoryId} 
     and status = #{status}
